            <div class="progress-bar" [style.width.%]="progress()"></div>
        </div>

        <ul class="watchlist" aria-label="Movies on your watchlist">
            @for (movie of movies(); track movie.id) {
                <!-- Clicking empty space on the row toggles watched; the checkbox, link and button handle their own clicks -->
                <li class="watchlist-item" [class.watched]="movie.watched" (click)="onRowClick($event, movie.id)">
                    <input type="checkbox" class="watched-checkbox" [checked]="movie.watched"
